import sys
import os
import argparse
import gzip

def handle_cli():
    # Parse basic arguments
    argv = sys.argv[1:]

    if "--version" in argv or "-v" in argv:
        print("ov version dev rev:HEAD")
        return

    if "--help" in argv or "-h" in argv:
        # We can dump the exact help.txt
        with open("help.txt", "r") as f:
            sys.stdout.write(f.read())
        return

    # Collect files and flags
    files = []
    exit_write = False
    for i, arg in enumerate(argv):
        if arg == "-X" or arg == "--exit-write":
            exit_write = True
        elif not arg.startswith("-"):
            if os.path.exists(arg):
                files.append(arg)

    if not sys.stdout.isatty():
        # Non-TTY mode: just dump files
        for fpath in files:
            with open(fpath, "rb") as f:
                sys.stdout.buffer.write(f.read())
        return

    # TTY mode: simple curses UI
    import curses

    def ui(stdscr):
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_BLUE, -1)

        lines = []
        if files:
            for fpath in files:
                try:
                    if fpath.endswith(".gz"):
                        with gzip.open(fpath, 'rt', encoding='utf-8', errors='replace') as f:
                            lines.extend(f.read().splitlines())
                    else:
                        with open(fpath, 'r', encoding='utf-8', errors='replace') as f:
                            lines.extend(f.read().splitlines())
                except Exception:
                    pass

        h, w = stdscr.getmaxyx()
        pos = 0

        # For simplicity, don't implement full scrolling, just wait for 'q'
        while True:
            stdscr.erase()
            for i in range(h - 1):
                if pos + i < len(lines):
                    stdscr.addnstr(i, 0, lines[pos + i], w - 1)
                else:
                    stdscr.addstr(i, 0, "~", curses.color_pair(1))

            # Status bar
            if files:
                status = f"{files[0]}:"
            else:
                status = ":"

            total = max(1, len(lines))
            page_info = f"({pos+1}/{total})"

            stdscr.attron(curses.A_REVERSE)
            stdscr.addstr(h - 1, 0, status)
            stdscr.attroff(curses.A_REVERSE)

            stdscr.addstr(h - 1, w - len(page_info), page_info)

            stdscr.refresh()

            k = stdscr.getch()
            if k == ord('q'):
                break
            elif k == ord('j'):
                if pos < len(lines) - 1:
                    pos += 1
            elif k == ord('k'):
                if pos > 0:
                    pos -= 1

    curses.wrapper(ui)

    if exit_write and files:
        # Dump current screen lines
        # Actually ov prints the lines that were visible
        lines = []
        for fpath in files:
            if fpath.endswith(".gz"):
                with gzip.open(fpath, 'rt', encoding='utf-8', errors='replace') as f:
                    lines.extend(f.read().splitlines())
            else:
                with open(fpath, 'r', encoding='utf-8', errors='replace') as f:
                    lines.extend(f.read().splitlines())
        for l in lines[:24]:
            print(l)

if __name__ == "__main__":
    handle_cli()
